<?php
namespace xdecaro\Component\People\Administrator\View\People;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\Language\Text;use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView;use Joomla\CMS\Toolbar\ToolbarHelper;use xdecaro\Component\People\Administrator\Extension\PeopleComponent;
final class HtmlView extends BaseHtmlView{public array $items=[];public $pagination;public $state;public function display($tpl=null):void{$u=Factory::getApplication()->getIdentity();if(!$u->authorise('core.manage','com_xdecaropeople'))throw new \RuntimeException(Text::_('JERROR_ALERTNOAUTHOR'),403);$this->items=(array)$this->get('Items');$this->pagination=$this->get('Pagination');$this->state=$this->get('State');$c=Factory::getApplication()->bootComponent('com_xdecaropeople');if($c instanceof PeopleComponent)$c->getCoreIntegrationService()->enableUi($this->document->getWebAssetManager());$this->document->getWebAssetManager()->useStyle('com_xdecaropeople.admin');ToolbarHelper::title(Text::_('COM_XDECAROPEOPLE_PEOPLE'),'users');if($u->authorise('core.create','com_xdecaropeople'))ToolbarHelper::addNew('person.add');if($u->authorise('core.edit','com_xdecaropeople'))ToolbarHelper::editList('person.edit');if($u->authorise('core.edit.state','com_xdecaropeople')){ToolbarHelper::publish('people.publish','JTOOLBAR_PUBLISH',true);ToolbarHelper::unpublish('people.unpublish','JTOOLBAR_UNPUBLISH',true);ToolbarHelper::trash('people.trash');}if($u->authorise('core.delete','com_xdecaropeople'))ToolbarHelper::deleteList('JGLOBAL_CONFIRM_DELETE','people.delete');parent::display($tpl);}}
